        ('100137453'),('100137450'),('100137455')
    ) as t(entrata_property_id)),

entrata_properties as (
    select
        p.property_id,
        p.property_name,
        parse_json(p.property_source_id):"property_id"::string as entrata_pid,
        case
            when e.entrata_property_id is not null then 'Enhanced'
            else 'Basic'
        end as integration_type,
        kf.total_units
    from prod.common.d_properties p
    left join prod.staging.stg_petscreening__integrations i
        on p.integration_id = i.integration_id
    left join prod.petscreening.petscreening__property_key_facts kf
        on p.property_id = kf.property_id
    left join enhanced_property_ids e
        on parse_json(p.property_source_id):"property_id"::string = e.entrata_property_id
    where p.property_source_name = 'entrata'
      and i.system = 'entrata'
      and i.state = 'enabled'
      and p.integration_status = 'enabled'
      and p.property_status = 'active'
),

-- Flatten pet charges from getLeases
-- Entrata chargeCode = literal string ("Pet Rent", "Pet Fee", etc.)
lease_charges as (
    select
        t.property_id,
        t.email,
        t.source_lease_id as lease_id,
        t.customer_id,
        charges.value:chargeCode::string as charge_code,
        charges.value:amount::number(10,2) as amount,
        charges.value:frequency::string as frequency,
        case
            when lower(charges.value:chargeCode::string) like '%pet%'
              or lower(charges.value:chargeCode::string) like '%animal%'
            then true else false
        end as is_pet_charge
    from prod.staging.stg_pmc_integrations_entrata__getleases t,
    lateral flatten(input => try_parse_json(t.scheduled_charges_array)) charges
    where t.lease_customer_status not in ('Cancelled', 'Applicant')
      and t.application_completed_on_date is not null
),

-- Pre-aggregate unit totals to avoid fan-out
unit_totals as (
    select integration_type, sum(coalesce(total_units, 0)) as total_units
    from entrata_properties
    group by 1
)

select
    ep.integration_type,
    count(distinct ep.property_id) as properties,
    max(ut.total_units) as total_units,
    count(distinct u.user_key) as total_ps_users,

    count(distinct case when lc.is_pet_charge and lc.amount > 0 then u.user_key end)
        as users_paying_pet_rent,

    sum(case when lc.is_pet_charge and lower(lc.frequency) = 'monthly' then lc.amount else 0 end)
        as total_monthly_pet_rent,

    div0(
        sum(case when lc.is_pet_charge and lower(lc.frequency) = 'monthly' then lc.amount else 0 end),
        nullif(count(distinct case when lc.is_pet_charge and lc.amount > 0 then u.user_key end), 0)
    ) as avg_monthly_pet_rent_per_paying_user,

    div0(
        sum(case when lc.is_pet_charge and lower(lc.frequency) = 'monthly' then lc.amount else 0 end),
        nullif(count(distinct u.user_key), 0)
    ) as pet_rent_per_ps_user,

    round(div0(
        count(distinct case when lc.is_pet_charge and lc.amount > 0 then u.user_key end) * 100.0,
        nullif(count(distinct u.user_key), 0)
    ), 1) as pct_users_paying_pet_rent,

    -- Asset value math
    sum(case when lc.is_pet_charge and lower(lc.frequency) = 'monthly' then lc.amount else 0 end) * 12
        as annual_pet_rent,
    sum(case when lc.is_pet_charge and lower(lc.frequency) = 'monthly' then lc.amount else 0 end) * 12 / 0.05
        as asset_value_at_5pct_cap

from entrata_properties ep
left join unit_totals ut on ep.integration_type = ut.integration_type
left join prod.petscreening.petscreening__user_enriched u
    on u.property_id = ep.property_id
    and u.property_source_name = 'entrata'
    and u.compliance_status = 'compliant'
    and u.user_pet_type = 'household'
    and u.user_pet_status = 'active'
    and u.user_email is not null
    and trim(u.user_email) <> ''
left join lease_charges lc
    on lower(trim(lc.email)) = lower(trim(u.user_email))
    and lc.property_id = ep.property_id
group by 1
order by 1;


