    ) as t(entrata_property_id)),

entrata_properties as (
    select
        p.property_id,
        p.property_name,
        parse_json(p.property_source_id):"property_id"::string as entrata_pid,
        case
            when e.entrata_property_id is not null then 'Enhanced'
            else 'Basic'
        end as integration_type
    from prod.common.d_properties p
    left join prod.staging.stg_petscreening__integrations i
        on p.integration_id = i.integration_id
    left join enhanced_property_ids e
        on parse_json(p.property_source_id):"property_id"::string = e.entrata_property_id
    where p.property_source_name = 'entrata'
      and i.system = 'entrata'
      and i.state = 'enabled'
      and p.integration_status = 'enabled'
      and p.property_status = 'active'
),

-- Who is paying pet charges (from getLeases scheduled charges)
-- Expanded by lease: if ANY customer on a lease pays, all customers on that lease count
paying_leases as (
    select distinct
        t.property_id,
        t.source_lease_id as lease_id
    from prod.staging.stg_pmc_integrations_entrata__getleases t
    inner join entrata_properties ep on t.property_id = ep.property_id,
    lateral flatten(input => try_parse_json(t.scheduled_charges_array)) charges
    where t.lease_customer_status not in ('Cancelled', 'Applicant')
      and t.application_completed_on_date is not null
      and (lower(charges.value:chargeCode::string) like '%pet%'
           or lower(charges.value:chargeCode::string) like '%animal%')
      and charges.value:amount::number(10,2) > 0
),

-- All emails on paying leases = "paying" (lease-level expansion)
paying_emails as (
    select distinct
        t.property_id,
        lower(trim(t.email)) as email
    from prod.staging.stg_pmc_integrations_entrata__getleases t
    inner join paying_leases pl
        on t.property_id = pl.property_id
        and t.source_lease_id = pl.lease_id
    where t.email is not null and trim(t.email) <> ''
),

-- Freshness: emails that exist in current API data (filter stale profiles)
api_emails as (
    select distinct
        t.property_id,
        lower(trim(t.email)) as email
    from prod.staging.stg_pmc_integrations_entrata__getleases t
    inner join entrata_properties ep on t.property_id = ep.property_id
    where t.email is not null and trim(t.email) <> ''
      and t.lease_customer_status not in ('Cancelled', 'Applicant')
),

-- Active household profiles in PetScreening
ps_profiles as (
    select distinct
        ep.property_id,
        ep.property_name,
        ep.integration_type,
        u.user_key,
        u.user_email,
        u.user_first_name,
        u.user_last_name
    from prod.common.d_units du
    join entrata_properties ep on du.property_id = ep.property_id
    join prod.petscreening.petscreening__user_enriched u
        on du.unit_id = u.unit_id
    where du.unit_source = 'entrata'
      and u.compliance_status = 'compliant'
      and u.user_pet_type = 'household'
      and u.user_pet_status = 'active'
      and u.user_email is not null
      and trim(u.user_email) <> ''
),

-- Flag paying vs leaking (with freshness filter)
pet_leak as (
    select
        p.property_id,
        p.property_name,
        p.integration_type,
        p.user_key,
        p.user_email,
        p.user_first_name,
        p.user_last_name,
        case when pe.email is not null then 1 else 0 end as is_paying
    from ps_profiles p
    -- Freshness: only profiles whose email appears in current getLeases data
    inner join api_emails ae
        on p.property_id = ae.property_id
        and lower(trim(p.user_email)) = ae.email
    left join paying_emails pe
        on p.property_id = pe.property_id
        and lower(trim(p.user_email)) = pe.email
)

select
    integration_type,
    count(distinct property_id) as properties,
    count(distinct user_key) as total_household_profiles,
    count(distinct case when is_paying = 1 then user_key end) as paying,
    count(distinct case when is_paying = 0 then user_key end) as not_paying_pet_rent,
    round(div0(
        count(distinct case when is_paying = 0 then user_key end) * 100.0,
        nullif(count(distinct user_key), 0)
    ), 1) as pct_leaking
from pet_leak
group by 1
order by 1;

-- For detailed leak list:
-- select * from pet_leak where is_paying = 0 order by property_name, user_last_name;
